// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    Private_Bank c;
    Log lg;

    function setUp() public {
        lg = new Log();
        c = new Private_Bank(address(lg));
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, c.MinDeposit() + 1, type(uint256).max / 2);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        // Universal rule: a successful Deposit above MinDeposit is recorded in the
        // Log's History with Sender == depositor and Val == deposited amount.
        (address sender, , uint256 val, ) = lg.History(0);
        assertTrue(sender == actor && val == amount);
    }
}
